// Constructive q8 common-cycle inference, control-only. Algebraic block proposals.
#include <bits/stdc++.h>
using namespace std;
constexpr int N=29,Q=8,L=7,G=47;using U=uint32_t;using B=uint64_t;using Perm=array<int,N>;using Key=array<int,Q>;using Vec=array<uint8_t,Q>;using Maps=array<array<uint8_t,N>,Q>;using Clock=chrono::steady_clock;
constexpr U ALL=(1u<<N)-1;const string SYM="0123456789abcdefghijklmnopqrs";
const vector<string> ALPHA={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
const vector<int> SHAPE={8,3,6,2,5,3,2,3,5,7,3,4,10,8,3,5,8,4,3,4,5,4,3,5,1,3,5,5,3,4,2,6,5,3,8,5,4,8,2,3,4,6,6,3,2,10,2};
const vector<int> HELD={4,2,2,6,6,2,13,6,4,2,7,7,2,6,3,3};
int md(int x){x%=N;return x<0?x+N:x;}int inv[N],mul[N][N],sub[N][N];B pow29[14];
int val(char c){auto p=SYM.find(c);if(p==string::npos)throw runtime_error("bad rune");return p;}
U rot(U x,int d){return d?((x<<d)|(x>>(N-d)))&ALL:x;}
struct RNG{uint64_t x;explicit RNG(uint64_t s):x(s?s:1){}uint64_t next(){x^=x>>12;x^=x<<25;x^=x>>27;return x*2685821657736338717ull;}int pick(int n){return next()%n;}double real(){return (next()>>11)*0x1.0p-53;}template<class T>void shuffleV(vector<T>&v){for(int i=int(v.size())-1;i>0;--i)swap(v[i],v[pick(i+1)]);}};
struct Dictionary{
 vector<vector<string>> by=vector<vector<string>>(60);unordered_set<string> words,prefix;array<unordered_set<B>,14> codes;array<array<unordered_map<B,uint16_t>,13>,14>wild;array<double,14> ratio{};
 B code(const string&w)const{B c=0;for(size_t i=0;i<w.size();++i)c+=B(val(w[i]))*pow29[i];return c;}
 void addVariants(const string&word){string s;for(size_t i=0;i<word.size();i++){char c=toupper(word[i]);if(c=='Q'&&i+1<word.size()&&toupper(word[i+1])=='U'){s+="CW";i++;continue;}if(c=='V')c='U';if(c=='K'||c=='Q')c='C';if(c=='Z')c='S';s+=c;}string w;auto rec=[&](auto&&self,size_t i)->void{if(i==s.size()){words.insert(w);return;}for(int n=1;n<=3&&i+n<=s.size();n++){string t=s.substr(i,n);int x=-1;if(n==3){if(t=="ING")x=21;}else{auto p=find(ALPHA.begin(),ALPHA.end(),t);if(p!=ALPHA.end())x=p-ALPHA.begin();}if(x>=0){w+=SYM[x];self(self,i+n);w.pop_back();}}};rec(rec,0);}
 void load(const string&path){ifstream f(path);if(!f)throw runtime_error("dictionary missing");string line;while(getline(f,line)){istringstream in(line);string w,n,extra;if(!(in>>w>>n)||in>>extra||w.empty()||n.empty()||!all_of(w.begin(),w.end(),[](char c){return c>='a'&&c<='z';})||!all_of(n.begin(),n.end(),[](char c){return c>='0'&&c<='9';}))continue;addVariants(w);}if(words.size()!=38910)throw runtime_error("base dictionary size "+to_string(words.size()));for(auto&w:words){by[w.size()].push_back(w);if(w.size()==11)prefix.insert(w.substr(0,10));if(w.size()<=13){B c=code(w);codes[w.size()].insert(c);for(int i=0;i<int(w.size());++i)if(w[i]!='0')++wild[w.size()][i][c-B(val(w[i]))*pow29[i]];}}for(auto&v:by)sort(v.begin(),v.end());for(int n=1;n<=13;++n)ratio[n]=(1.-3./47.)*double(pow29[n])/(8.*max<size_t>(1,by[n].size()));cout<<"DICTIONARY words="<<words.size()<<" prefixes="<<prefix.size()<<endl;}
};
Dictionary D;
struct Action{Perm pi;Key k;};
Maps maps(const Action&a){Perm ip{};for(int i=0;i<N;++i)ip[a.pi[i]]=i;Maps m{};for(int j=0;j<Q;++j)for(int c=0;c<N;++c)m[j][c]=ip[sub[a.pi[c]][a.k[j]]];return m;}
string encode(const string&w,const Action&a,int j){Perm ip{};for(int i=0;i<N;++i)ip[a.pi[i]]=i;string c;for(char ch:w){int p=val(ch);if(!p)c+='0';else{c+=SYM[ip[(a.pi[p]+a.k[j])%N]];j=(j+1)&7;}}return c;}
bool truthPath(const string&c,const string&w,const Action&a){for(int j=0;j<Q;++j)if(encode(w,a,j)==c)return true;return false;}
string signature(const Action&a){auto m=maps(a);string best;for(int r=0;r<Q;++r){string s;for(int j=0;j<Q;++j)for(int c=0;c<N;++c)s+=char(m[(j+r)&7][c]);if(r==0||s<best)best=move(s);}return best;}
Action randomAction(RNG&r){Action a;iota(a.pi.begin(),a.pi.end(),0);for(int i=N-1;i>1;--i)swap(a.pi[i],a.pi[1+r.pick(i)]);a.k[0]=1;for(int i=1;i<Q;++i)a.k[i]=r.pick(N);if(equal(a.k.begin(),a.k.begin()+4,a.k.begin()+4))a.k[4]=md(a.k[4]+1);return a;}
struct Edge{uint8_t c,p,j;};
struct Option{array<Edge,13>e{};uint8_t n=0,start=0;B plain=0;};
Option option(const string&c,const string&w,int start){Option o;o.start=start;o.plain=D.code(w);int j=start;for(int i=0;i<int(c.size());++i){int p=val(w[i]),x=val(c[i]);if(!p){assert(x==0);continue;}o.e[o.n++]={uint8_t(x),uint8_t(p),uint8_t(j)};j=(j+1)&7;}return o;}
string decodeCode(B code,int n){string w(n,'0');for(char&c:w){c=SYM[code%N];code/=N;}return w;}
struct WordEval{int count=0,all=0,near=0;vector<Option> matches;};
struct Eval{double exact=0,soft=0;int support=0,dead=0;array<vector<Option>,G> matches;};
struct Group{string text;array<uint8_t,13> c{};int n;vector<Option> opts;};
Group group(const string&c){Group g;g.text=c;g.n=c.size();for(int i=0;i<g.n;++i)g.c[i]=val(c[i]);return g;}
WordEval evaluateWord(const Group&g,const Maps&m,bool collect,bool near){WordEval out;array<uint8_t,13> p{};auto rec=[&](auto&&self,int i,int j,int start,B code)->void{if(i==g.n){++out.all;bool exact=D.codes[g.n].count(code);if(exact){++out.count;if(collect){Option o;o.plain=code;o.start=start;int z=start;for(int q=0;q<g.n;++q)if(p[q]){o.e[o.n++]={g.c[q],p[q],uint8_t(z)};z=(z+1)&7;}out.matches.push_back(o);}}if(near){for(int q=0;q<g.n;++q)if(p[q]){auto it=D.wild[g.n][q].find(code-B(p[q])*pow29[q]);if(it!=D.wild[g.n][q].end())out.near+=it->second-exact;}}return;}int x=g.c[i];if(!x){p[i]=0;self(self,i+1,j,start,code);}int z=m[j][x];if(z){p[i]=z;self(self,i+1,(j+1)&7,start,code+B(z)*pow29[i]);}};for(int j=0;j<Q;++j)rec(rec,0,j,j,0);return out;}
Eval evaluate(const vector<Group>&gs,const Action&a,bool collect,bool near){auto m=maps(a);Eval e;for(int i=0;i<int(gs.size());++i){auto w=evaluateWord(gs[i],m,collect,near);e.support+=(w.count>0);e.dead+=(w.all==0);double bg=1e-9+(3./47.)*w.all/8.;double lex=D.ratio[gs[i].n]*w.count;e.exact+=log(bg+lex);e.soft+=log(bg+lex+(near?.025*D.ratio[gs[i].n]*w.near:0));if(collect)e.matches[i]=move(w.matches);}return e;}
Vec addv(const Vec&a,const Vec&b){Vec c{};for(int i=0;i<Q;i++)c[i]=(a[i]+b[i])%N;return c;}
Vec minusv(const Vec&a,const Vec&b){Vec c{};for(int i=0;i<Q;i++)c[i]=sub[a[i]][b[i]];return c;}
Vec unit(int j){Vec x{};x[j]=1;return x;}
struct KeySpace{int d=7;array<Vec,Q>a{};array<uint8_t,Q>vars{};KeySpace(){a[0][L]=1;for(int i=1;i<Q;i++){a[i][i-1]=1;vars[i-1]=i;}}
 Vec project(const Vec&v)const{Vec x{};for(int j=0;j<Q;j++)if(v[j]){for(int k=0;k<d;k++)x[k]=(x[k]+mul[v[j]][a[j][k]])%N;x[L]=(x[L]+mul[v[j]][a[j][L]])%N;}return x;}
 bool impose(const Vec&v){Vec eq=project(v);int pivot=d-1;while(pivot>=0&&!eq[pivot])pivot--;if(pivot<0)return !eq[L];int last=d-1,rec=inv[eq[pivot]];for(auto&r:a){int f=mul[r[pivot]][rec];if(f){for(int j=0;j<d;j++)if(j!=pivot)r[j]=sub[r[j]][mul[f][eq[j]]];r[L]=sub[r[L]][mul[f][eq[L]]];}if(pivot!=last)r[pivot]=r[last];r[last]=0;}vars[pivot]=vars[last];vars[last]=0;d--;return true;}
 bool primitive()const{for(int i=0;i<4;i++)if(a[i]!=a[i+4])return true;return false;}
 Key evaluate(const Vec&params)const{Key k{};for(int j=0;j<Q;j++){int x=a[j][L];for(int i=0;i<d;i++)x+=params[i]*a[j][i];k[j]=x%N;}return k;}
};
struct Graph{array<uint8_t,N>r{},sz{};array<Vec,N>off{};int comps=N;KeySpace k;Graph(){for(int x=0;x<N;x++){r[x]=x;sz[x]=1;}}
 bool edge(Edge e){int c=e.c,p=e.p,j=e.j,rc=r[c],rp=r[p];Vec shift=minusv(addv(off[p],unit(j)),off[c]);if(rc==rp)return k.impose(shift);if(sz[rc]<=sz[rp]){for(int x=0;x<N;x++)if(r[x]==rc){r[x]=rp;off[x]=addv(off[x],shift);}sz[rp]+=sz[rc];sz[rc]=0;}else{for(int x=0;x<N;x++)if(r[x]==rp){r[x]=rc;off[x]=minusv(off[x],shift);}sz[rc]+=sz[rp];sz[rp]=0;}if(--comps==1){Vec sum{};for(int x=0;x<N;x++)sum=addv(sum,off[x]);if(!k.impose(sum))return false;}return true;}
 bool valid()const{if(!k.primitive())return false;array<Vec,N>v{};for(int x=0;x<N;x++)v[x]=k.project(off[x]);for(int x=0;x<N;x++)for(int y=0;y<x;y++)if(r[x]==r[y]&&v[x]==v[y])return false;return true;}
 bool extend(const Option&o){for(int i=0;i<o.n;i++)if(!edge(o.e[i]))return false;return valid();}
};
// Finite packing of disjoint cyclic component translations under a candidate numeric key.
struct Packer{const Graph&g;const Key&k;const Perm&prefer;RNG&r;double keepBias;array<int,N>off{},base{};array<U,N>shape{};vector<int> roots,single;array<vector<int>,N> order;uint64_t nodes=0,cap=350;Perm result{};
 Packer(const Graph&g_,const Key&k_,const Perm&p,RNG&r_,double bias):g(g_),k(k_),prefer(p),r(r_),keepBias(bias){}
 bool run(){for(int i=0;i<N;++i){int s=0;for(int j=0;j<Q;++j)s+=g.off[i][j]*k[j];off[i]=s%N;int rt=g.r[i];if(shape[rt]&(1u<<off[i]))return false;shape[rt]|=1u<<off[i];}int f=g.r[0];base[f]=md(-off[0]);U used=rot(shape[f],base[f]);for(int i=0;i<N;++i)if(g.r[i]==i&&i!=f){if(g.sz[i]==1){single.push_back(i);continue;}roots.push_back(i);vector<pair<double,int>>scores;for(int z=0;z<N;++z){int agree=0;for(int x=0;x<N;++x)if(g.r[x]==i&&md(z+off[x])==prefer[x])++agree;scores.push_back({keepBias*agree+r.real(),z});}sort(scores.begin(),scores.end(),greater<pair<double,int>>());for(auto p:scores)order[i].push_back(p.second);}return rec(used,0);}
 bool rec(U used,int depth){if(++nodes>cap)return false;if(depth==int(roots.size())){vector<int>free;for(int i=0;i<N;++i)if(!(used&(1u<<i)))free.push_back(i);r.shuffleV(single);vector<int>later;for(int x:single){int z=prefer[x];auto it=find(free.begin(),free.end(),z);if(it!=free.end()&&r.real()<min(.95,keepBias/2)){base[x]=md(z-off[x]);free.erase(it);}else later.push_back(x);}r.shuffleV(free);for(size_t i=0;i<later.size();++i)base[later[i]]=md(free[i]-off[later[i]]);for(int x=0;x<N;++x)result[x]=md(base[g.r[x]]+off[x]);assert(result[0]==0);return true;}
 int best=-1,bc=N+1;for(int z=depth;z<int(roots.size());++z){int rt=roots[z],cnt=0;for(int p:order[rt])cnt+=!(used&rot(shape[rt],p));if(!cnt)return false;if(cnt<bc){bc=cnt;best=z;}}swap(roots[depth],roots[best]);int rt=roots[depth];for(int p:order[rt]){U m=rot(shape[rt],p);if(used&m)continue;base[rt]=p;if(rec(used|m,depth+1))return true;if(nodes>cap)break;}swap(roots[depth],roots[best]);return false;}
};
struct Stats{uint64_t evals=0,blocks=0,blockOK=0,injects=0,injectOK=0,packTries=0,accepted=0,swaps=0,steps=0;};
optional<Action> complete(const Graph&g,const Action&cur,RNG&r,Stats&stats,int tries=8){for(int t=0;t<tries;++t){Vec v{};for(int j=0;j<g.k.d;++j)v[j]=cur.k[g.k.vars[j]];if(t||r.real()<.45){int n=t<3?1:1+r.pick(max(1,g.k.d));for(int z=0;z<n&&g.k.d;++z)v[r.pick(g.k.d)]=r.pick(N);}Key k=g.k.evaluate(v);if(equal(k.begin(),k.begin()+4,k.begin()+4))continue;double bias=t==0?2.0:(r.real()<.4?0.0:.45);Packer pack(g,k,cur.pi,r,bias);++stats.packTries;if(pack.run()){Action a{pack.result,k};return a;}}return nullopt;}
void prepare(vector<Group>&gs){for(auto&g:gs){for(const string&w:D.by[g.n]){bool good=true;for(int i=0;i<g.n;++i)if(w[i]=='0'&&g.c[i]){good=false;break;}if(!good)continue;for(int st=0;st<Q;++st){Option o=option(g.text,w,st);bool ok=true;for(int i=0;i<o.n&&ok;++i){auto a=o.e[i];if(!a.j&&a.c==a.p){ok=false;break;}for(int j=0;j<i;++j){auto b=o.e[j];if(a.j==b.j&&(((a.c==b.c)!=(a.p==b.p))||((a.c==a.p)!=(b.c==b.p)))){ok=false;break;}}}if(ok)g.opts.push_back(o);}}}uint64_t total=0;for(auto&g:gs)total+=g.opts.size();cout<<"DOMAINS total="<<total<<endl;}
// Near-word proposals preserve the current F history and phase while replacing a single consuming rune.
vector<Option> nearOptions(const Group&g,const Maps&m,RNG&r){vector<Option>out;array<uint8_t,13>p{};auto rec=[&](auto&&self,int i,int j,int start,B code)->void{if(i==g.n){for(int q=0;q<g.n;++q)if(p[q]){B base=code-B(p[q])*pow29[q];if(!D.wild[g.n][q].count(base))continue;for(int x=1;x<N;++x)if(x!=p[q]&&D.codes[g.n].count(base+B(x)*pow29[q]))out.push_back(option(g.text,decodeCode(base+B(x)*pow29[q],g.n),start));}return;}int x=g.c[i];if(!x){p[i]=0;self(self,i+1,j,start,code);}int z=m[j][x];if(z){p[i]=z;self(self,i+1,(j+1)&7,start,code+B(z)*pow29[i]);}};for(int j=0;j<Q;++j)rec(rec,0,j,j,0);r.shuffleV(out);return out;}
void replayOptions(const vector<Group>&gs,const Action&a,const Eval&e){for(int i=0;i<int(gs.size());++i)for(const auto&o:e.matches[i])if(encode(decodeCode(o.plain,gs[i].n),a,o.start)!=gs[i].text)throw runtime_error("exact support replay mismatch");}
struct State{Action a;Eval e;};
int overlap(const Option&o,const Maps&m){int n=0;for(int i=0;i<o.n;++i){auto e=o.e[i];n+=(m[e.j][e.c]==e.p);}return n;}
optional<Action> blockMove(const vector<Group>&gs,const State&s,RNG&r,Stats&stats,bool inject){++stats.blocks;Graph g;vector<int>support,unsupported;for(int i=0;i<G;++i)(s.e.matches[i].empty()?unsupported:support).push_back(i);r.shuffleV(support);int limit=4+r.pick(19),used=0;vector<bool>held(G);if(r.real()<.12)limit=0;for(int i:support){if(used>=limit)break;if(r.real()<.25)continue;const auto&o=s.e.matches[i][r.pick(s.e.matches[i].size())];if(used+o.n>limit+4)continue;Graph h=g;if(!h.extend(o))throw runtime_error("current supported option incompatible");g=move(h);used+=o.n;held[i]=true;}
 if(!inject){auto out=complete(g,s.a,r,stats);stats.blockOK+=bool(out);return out;}
 ++stats.injects;vector<int>targets;for(int i=0;i<G;++i)if(!held[i]&&!gs[i].opts.empty())targets.push_back(i);if(targets.empty())return nullopt;int target=targets[r.pick(targets.size())];for(int z=0;z<3;++z){int j=targets[r.pick(targets.size())];if(gs[j].n>gs[target].n&&r.real()<.7)target=j;}auto m=maps(s.a);if(r.real()<.8){vector<int>nearTargets=unsupported;r.shuffleV(nearTargets);stable_sort(nearTargets.begin(),nearTargets.end(),[&](int a,int b){return gs[a].n>gs[b].n;});int tested=0;for(int id:nearTargets){if(held[id])continue;if(++tested>5)break;auto near=nearOptions(gs[id],m,r);int attempts=0;for(auto&o:near){if(++attempts>12)break;Graph h=g;if(!h.extend(o))continue;auto out=complete(h,s.a,r,stats,5);if(out){if(encode(decodeCode(o.plain,gs[id].n),*out,o.start)!=gs[id].text)throw runtime_error("near injection replay");++stats.blockOK;++stats.injectOK;return out;}}}}
 const auto&opts=gs[target].opts;vector<pair<double,int>>cand;int samples=min<int>(96,opts.size());for(int z=0;z<samples;++z){int j=r.pick(opts.size());int hit=overlap(opts[j],m);cand.push_back({1.6*hit+r.real()*2.5,j});}sort(cand.begin(),cand.end(),greater<pair<double,int>>());int tried=0;for(auto [sc,j]:cand){Graph h=g;if(!h.extend(opts[j]))continue;if(++tried>5)break;auto out=complete(h,s.a,r,stats,5);if(out){if(!truthPath(gs[target].text,[&]{string w(gs[target].n,'0');B v=opts[j].plain;for(char&c:w){c=SYM[v%N];v/=N;}return w;}(),*out))throw runtime_error("injected option replay");++stats.blockOK;++stats.injectOK;return out;}}return nullopt;}
Action localMove(const Action&a,RNG&r){Action b=a;int t=r.pick(100);if(t<65){int x=1+r.pick(28),y=1+r.pick(28);swap(b.pi[x],b.pi[y]);}else if(t<94){int j=1+r.pick(7);b.k[j]=r.pick(29);}else{int i=1+r.pick(7),j=1+r.pick(7);swap(b.k[i],b.k[j]);}if(equal(b.k.begin(),b.k.begin()+4,b.k.begin()+4))b.k[4]=md(b.k[4]+1);return b;}
struct SearchResult{Action best;Eval score;Stats stats;vector<pair<Action,Eval>>top;size_t feasible=0;};
SearchResult search(const vector<Group>&gs,uint64_t seed,int steps,int replicas,int reportEvery){RNG r(seed);vector<State>states;const vector<double>temps={.7,1.3,2.5,4.5,8.,13.,20.,30.};SearchResult out;out.score.exact=-1e300;unordered_set<string> feasible;
 auto observe=[&](const Action&a,const Eval&e){if(e.exact>out.score.exact){out.best=a;out.score=e;cout<<"BEST step="<<out.stats.steps<<" exact="<<e.exact<<" soft="<<e.soft<<" support="<<e.support<<" dead="<<e.dead<<endl;}if(e.support>=44&&!e.dead){auto sig=signature(a);if(feasible.insert(sig).second){++out.feasible;auto verified=evaluate(gs,a,true,false);replayOptions(gs,a,verified);out.top.push_back({a,move(verified)});cout<<"FEASIBLE support="<<e.support<<" score="<<e.exact<<endl;}}};
 for(int i=0;i<replicas;++i){Action a=randomAction(r);auto e=evaluate(gs,a,true,true);states.push_back({a,move(e)});observe(states.back().a,states.back().e);}
 auto value=[&](const Eval&e,int i){double mix=i==0?.25:(i==1?.5:.85);return e.exact*(1.-mix)+e.soft*mix;};
 for(int step=0;step<steps;++step){++out.stats.steps;int i=step%replicas;auto&s=states[i];optional<Action> proposal;int t=r.pick(100);if(t<30)proposal=localMove(s.a,r);else proposal=blockMove(gs,s,r,out.stats,t>=48);if(proposal){auto e=evaluate(gs,*proposal,false,true);++out.stats.evals;observe(*proposal,e);double delta=value(e,i)-value(s.e,i);if(delta>=0||log(max(1e-300,r.real()))<delta/temps[i]){s.a=*proposal;s.e=evaluate(gs,s.a,true,true);++out.stats.accepted;}}
 if(step%(replicas*11)==replicas*11-1){for(int j=0;j+1<replicas;++j){auto&x=states[j];auto&y=states[j+1];double delta=(value(y.e,j)-value(x.e,j))/temps[j]+(value(x.e,j+1)-value(y.e,j+1))/temps[j+1];if(delta>=0||log(max(1e-300,r.real()))<delta){swap(x,y);++out.stats.swaps;}}}
 if(reportEvery&&step%reportEvery==reportEvery-1){cout<<"PROGRESS "<<step+1<<" evals="<<out.stats.evals<<" block="<<out.stats.blockOK<<"/"<<out.stats.blocks<<" inject="<<out.stats.injectOK<<"/"<<out.stats.injects<<" pack="<<out.stats.packTries<<" accepted="<<out.stats.accepted<<" best="<<out.score.exact<<" support="<<out.score.support<<endl;}
 }return out;}
struct Plant{Action a;vector<string>train,truth,held,heldTruth;string carry,carryTruth;};
bool support(const string&c,const Action&a){return evaluateWord(group(c),maps(a),false,false).count>0;}
string randomGpWord(mt19937&rng,int n){uniform_int_distribution<int>pick(0,N-1);string w;for(int i=0;i<n;i++)w+=SYM[pick(rng)];return w;}
Plant plant(uint32_t seed){mt19937 rng(seed);Plant p;iota(p.a.pi.begin(),p.a.pi.end(),0);shuffle(p.a.pi.begin()+1,p.a.pi.end(),rng);uniform_int_distribution<int>pickKey(0,N-1),pickPhase(0,Q-1);for(int j=0;j<Q;j++)p.a.k[j]=pickKey(rng);p.a.k[0]=1;p.a.k[4]=2;p.a.k[3]=0;auto choose=[&](int n){const auto&v=D.by[n];uniform_int_distribution<size_t>pick(0,v.size()-1);return v[pick(rng)];};for(int i=0;i<G;++i){int n=SHAPE[i];string w,c;if(i==12||i==43){for(int t=0;t<100000;++t){w=randomGpWord(rng,n);if(D.words.count(w))continue;c=encode(w,p.a,pickPhase(rng));if(!support(c,p.a))break;w.clear();c.clear();}assert(!w.empty()&&!c.empty());}else{w=choose(n);c=encode(w,p.a,pickPhase(rng));}p.truth.push_back(w);p.train.push_back(c);}for(int t=0;t<100000;++t){string w=randomGpWord(rng,11);if(D.words.count(w)||D.prefix.count(w.substr(0,10)))continue;string c=encode(w,p.a,pickPhase(rng));bool hit=false;for(auto&prefix:D.prefix)if(truthPath(c.substr(0,10),prefix,p.a)){hit=true;break;}if(hit)continue;p.carryTruth=w;p.carry=c;break;}assert(p.carry.size()==11);for(int n:HELD){string w=choose(n);p.heldTruth.push_back(w);p.held.push_back(encode(w,p.a,pickPhase(rng)));}return p;}
void printAction(const Action&a){cout<<" pi";for(int x:a.pi)cout<<" "<<x;cout<<" k";for(int x:a.k)cout<<" "<<x;cout<<endl;}
int main(int argc,char**argv){for(int i=0;i<N;++i)for(int j=0;j<N;++j){mul[i][j]=i*j%N;sub[i][j]=md(i-j);if(mul[i][j]==1)inv[i]=j;}pow29[0]=1;for(int i=1;i<14;++i)pow29[i]=pow29[i-1]*29;D.load(argv[1]);uint32_t seed=stoul(argv[2]);int steps=stoi(argv[3]),replicas=argc>4?stoi(argv[4]):8;bool null=argc>5&&stoi(argv[5]);assert(replicas>=1&&replicas<=8);auto p=plant(seed);if(null){RNG r(0x1234+seed);for(int i=0;i<G;++i){auto a=randomAction(r);p.train[i]=encode(p.truth[i],a,r.pick(Q));}}vector<Group>gs;for(auto&c:p.train)gs.push_back(group(c));prepare(gs);cout<<"BLIND seed="<<seed<<" steps="<<steps<<" replicas="<<replicas<<" null="<<null<<endl;auto t=Clock::now();auto result=search(gs,0x9c381d39ull+seed*17ull,steps,replicas,max(1000,steps/10));auto verified=evaluate(gs,result.best,true,false);replayOptions(gs,result.best,verified);auto oracle=evaluate(gs,p.a,false,true);bool exact=!null&&signature(result.best)==signature(p.a);int train=0,held=0,unique=0;bool carry=false;for(int i=0;i<G;++i)train+=truthPath(p.train[i],p.truth[i],result.best);for(int i=0;i<int(p.held.size());++i){held+=truthPath(p.held[i],p.heldTruth[i],result.best);auto w=evaluateWord(group(p.held[i]),maps(result.best),true,false);set<B>codes;for(auto&o:w.matches)codes.insert(o.plain);unique+=codes.size()==1&&codes.count(D.code(p.heldTruth[i]));}carry=truthPath(p.carry,p.carryTruth,result.best);cout<<"RESULT seed="<<seed<<" null="<<null<<" exact="<<exact<<" score="<<result.score.exact<<" support="<<result.score.support<<" dead="<<result.score.dead<<" oracle="<<oracle.exact<<" oracle_support="<<oracle.support<<" train_truth="<<train<<" held_truth="<<held<<" unique="<<unique<<" carry="<<carry<<" feasible="<<result.feasible<<" evals="<<result.stats.evals<<" blocks="<<result.stats.blockOK<<"/"<<result.stats.blocks<<" injection="<<result.stats.injectOK<<"/"<<result.stats.injects<<" pack="<<result.stats.packTries<<" accept="<<result.stats.accepted<<" swap="<<result.stats.swaps<<" seconds="<<chrono::duration<double>(Clock::now()-t).count()<<endl;cout<<"BEST_ACTION";printAction(result.best);cout<<"ORACLE_ACTION";printAction(p.a);}
